    slack: ending.slack, targets: pcs.filter((q) => !q.partial).map((q) => ({ t: r3(q.out), e: r3(targetAt(st, q.out + B / 2)) })), structure: { burst: st.burst, peak: st.peak, stop: st.stop, landing: st.landing }, grid: c.g,
