// ---------- measuring the rendered arrangement ----------

// 1 s of loudness each side of every join, and the 0.5 s loudness curve's jumps over 6 dB that the track does not have itself
export function measureArrangement(out, plan, rate = 48000) {
  const a = plan.arrange; if (!a) return { joins: [], jumps: [] };
  const rms = (t0, t1) => { const i0 = Math.max(0, Math.round(t0 * rate)), i1 = Math.min(out.L.length, Math.round(t1 * rate)); let s = 0; for (let i = i0; i < i1; i++) { const v = 0.5 * (out.L[i] + out.R[i]); s += v * v; } return 10 * Math.log10(s / Math.max(1, i1 - i0) + 1e-12); };
  // the window after a join stops where a fade begins or where a button's hit has played (its ring is a decay by design)
  const stopAt = (t) => Math.min(t + 1, a.endingKind === 'fade' ? a.fadeFrom : 1e9, a.button && t < a.button.at + 1e-6 && t > a.button.at - 0.1 ? a.button.at + a.button.hitLen : 1e9);
  const joins = a.joins.map((j) => { const e = stopAt(j.at), ok = e - j.at >= 0.3, b = rms(j.at - 1, j.at), af = ok ? rms(j.at, e) : b; return { at: j.at, before: r3(b), after: r3(af), diff: r3(af - b) }; });
  const jumps = [], skip = (t) => (a.duck && (Math.abs(t - a.duck.from) < 0.6 || Math.abs(t - a.duck.to) < 0.6)) || t > (a.fadeFrom || 1e9) - 0.05 && a.endingKind === 'fade';
  const win = 0.5, n = Math.floor(plan.duration / win), lv = []; for (let k = 0; k < n; k++) lv.push(rms(k * win, (k + 1) * win));
  for (let k = 1; k < n; k++) { const d = lv[k] - lv[k - 1], t = k * win; if (Math.abs(d) > 6 && !skip(t)) { const nearJoin = a.joins.some((j) => Math.abs(j.at - t) < 0.55); const inEnding = a.ending && a.ending.kind === 'natural' && t >= a.ending.musicEnds - 0.1, ring = a.button && t > a.button.at + 0.25; jumps.push({ at: r3(t), db: r3(d), atJoin: nearJoin, original: ring || (!nearJoin && (inEnding || !(a.button && t >= a.button.at - 0.1))) }); } }
  return { joins, jumps: jumps.filter((j) => !j.original) };
}

// ---------- the table ----------

const mmss = (t) => `${t.toFixed(2)}`;
export function arrangeLines(an, plan, measured = null) {
  const a = plan.arrange, map = an.map;
  if (!a) return plan.arrangeNote ? [`arrange  straight cut from ${plan.start.toFixed(2)}s${plan.looped ? ', looped on bar lines' : ''} — ${plan.arrangeNote}`] : [];
  const out = [`arrange  ${a.strategy}, ${a.endingKind === 'natural' ? "the track's own ending" : a.endingKind === 'button' ? 'a button ending (a home-chord hit that rings out)' : 'a fade (no usable ending)'} · ${a.joins.length} join${a.joins.length === 1 ? '' : 's'} · mean gap to the film's energy ${a.meanGap.toFixed(2)}${a.pickup > 0 ? ` · music starts ${Math.round(a.pickup * 1000)} ms into the track` : ''}`];
  let k = 0;
  while (k < a.steps.length) {
    let e = k; while (e + 1 < a.steps.length && a.steps[e + 1].bar === a.steps[e].bar + 1) e++;
    const t0 = a.steps[k].film, t1 = e + 1 < a.steps.length ? a.steps[e + 1].film : plan.duration;
    const b0 = map.bars[a.steps[k].bar], b1 = map.bars[a.steps[e].bar], from = k === 0 ? a.pickup : b0.start;
    const role = k === 0 ? 'opening' : e === a.steps.length - 1 && a.endingKind !== 'fade' ? (a.endingKind === 'button' ? 'hit' : 'ending') : 'middle';
    out.push(`  film ${mmss(t0)}–${mmss(Math.min(t1, plan.duration))}  ←  track ${mmss(from)}–${mmss(b1.end)}  bars ${a.steps[k].bar}${e > k ? `–${a.steps[e].bar}` : ''}  ${role}  ${[...new Set(a.steps.slice(k, e + 1).map((q) => q.label))].join('/')}  energy ${a.steps.slice(k, e + 1).map((q) => q.e.toFixed(2)).join(' ')}  (film wants ${a.steps.slice(k, e + 1).map((q) => q.target.toFixed(2)).join(' ')})`);
    k = e + 1;
  }
  a.joins.forEach((j, i) => {
    const m = measured?.joins?.[i];
    out.push(`  join ${mmss(j.at)}  ${j.kind === 'beat3' ? `beat 4 of bar ${j.from} → beat 4 of bar ${j.to - 1}` : `bar ${j.from}→${j.to}`}  ${j.chords}  smooth ${j.score.toFixed(2)} ${j.score >= GOOD_JOIN ? 'good' : j.score >= OK_JOIN ? 'ok' : 'rough — may be audible'}  loudness ${m ? `${m.before.toFixed(1)}→${m.after.toFixed(1)} dB (${m.diff >= 0 ? '+' : ''}${m.diff.toFixed(1)}, measured over 1 s each side)` : `${j.dLoud >= 0 ? '+' : ''}${j.dLoud.toFixed(1)} dB`}${Math.abs(j.gain) >= 0.05 ? `, ${j.gain >= 0 ? '+' : ''}${j.gain.toFixed(1)} dB static gain on what follows` : ''}  ${j.phrase ? 'phrase to phrase' : 'mid-phrase'}${j.posMatch ? ', same place in the progression' : ''}`);
  });
  const en = a.ending;
  out.push(en.kind === 'natural' ? `  end   the track's own ending: its last ${en.bars} bars (${(en.musicEnds - en.fromFilm).toFixed(1)} s, ${en.type}, ${en.decaySec.toFixed(1)} s of decay) play on to the end of the music at film ${mmss(en.musicEnds)}s${Math.abs(en.slack) > 0.05 ? ` (${en.slack > 0 ? `${en.slack.toFixed(2)} s of silence before the last frame` : `${(-en.slack).toFixed(2)} s clipped from its decay`})` : ''}${en.landing != null ? ` · strongest accent in the tail (${en.chord}${en.tonic ? ', home chord' : ''}) at film ${mmss(en.landing)}s${en.finalChord != null && Math.abs(en.finalChord - en.landing) > 0.05 ? `; the final chord (${en.finalChordName}) starts at film ${mmss(en.finalChord)}s` : ''}: land the end card on whichever you want` : ''}`
    : en.kind === 'button' ? `  end   button (synthetic: the ring is made, not the track's): a ${en.chord}${en.tonic ? ' (home chord)' : ''} hit at film ${mmss(en.landing)}s rings out in a reverb tail of ${a.button.tail.toFixed(1)} s to the last frame: land the end card at ${mmss(en.landing)}s`
    : `  end   no usable ending (${en.why}; no button hit fits either): the last bar rings from ${mmss(en.fadeFrom)}s into a fade`);
  if (a.duck) out.push(`  stop  ${mmss(a.duck.from)}–${mmss(a.duck.to)}s ducked ${a.duck.db} dB on whole beats (declared)`);
  for (const e of a.events) out.push(`  ${e.name.padEnd(5)} ${mmss(e.t)}s ${Math.abs(e.offMs) <= GRID_SLACK * 1000 ? 'is on a bar line' : `is ${Math.abs(e.offMs)} ms ${e.offMs > 0 ? 'after' : 'before'} the nearest bar line`}${e.lift ? `; ${e.lift.how === 'on' ? 'a real lift of the track lands on it' : `a real lift of the track lands ${e.lift.how} (${mmss(e.lift.at)}s)`} (step ${e.lift.step.toFixed(2)})` : ''}`);
  for (const t of a.suggest) out.push(`  hint  ${t}`);
  const alt = a.alternatives.filter((x) => x.strategy !== a.strategy || x.ending !== a.endingKind).slice(0, 3);
  if (alt.length) out.push(`  also tried: ${alt.map((x) => `${x.strategy} + ${x.ending} (score ${x.score.toFixed(2)}, ${x.joins} join${x.joins === 1 ? '' : 's'})`).join(' · ')}`);
  const sg = a.suggestion;
  if (sg?.adjusted) {
    const d = (v) => `${v.duration} s${v.moved.burst != null ? `, burst ${v.moved.burst}` : ''}${v.moved.peak != null ? `, peak ${v.moved.peak}` : ''}${v.moved.landing != null ? `, landing ${v.moved.landing}` : ''}`;
    out.push(`  film as written:   ${plan.duration} s  score ${sg.asIs.score.toFixed(2)}  ${sg.asIs.joins} join${sg.asIs.joins === 1 ? '' : 's'}, ${sg.asIs.endingKind === 'natural' ? `the track's own ending (${sg.asIs.endingSeconds.toFixed(1)} s)` : sg.asIs.endingKind}`);
    out.push(`  film adjusted:     ${d(sg.adjusted)}  score ${sg.adjusted.score.toFixed(2)}  ${sg.adjusted.joins} join${sg.adjusted.joins === 1 ? '' : 's'}, ${sg.adjusted.endingKind === 'natural' ? `the track's own ending (${sg.adjusted.endingSeconds.toFixed(1)} s)` : sg.adjusted.endingKind}`);
    out.push(sg.recommend ? `  hint  recommended: the adjusted film buys ${sg.gain.join(', ')}` : '  hint  the adjusted film scores about the same: keep the film as written');
  }
  const fd = a.fitDurations?.[0];
  if (fd && Math.abs(fd.seconds - plan.duration) > 0.05 && Math.abs(fd.seconds - plan.duration) <= a.barLen) out.push(`  hint  a film of ${fd.seconds.toFixed(1)} s needs one join only (first ${fd.openingBars} bars, then the ending from bar ${fd.endingFrom}${fd.lifts.length ? `; its lifts at ${fd.lifts.join(', ')} s` : ''}): ${plan.duration > fd.seconds ? 'cut' : 'extend'} the film by ${Math.abs(fd.seconds - plan.duration).toFixed(1)} s and the music needs no re-cut`);
  for (const j of measured?.jumps || []) out.push(`warning  loudness jumps ${j.db > 0 ? '+' : ''}${j.db.toFixed(1)} dB between the 0.5 s around film ${mmss(j.at)}s${j.atJoin ? ' (a join)' : ''} — not something the track does itself`);
  for (const n of a.notes) out.push(`warning  ${n}`);
  return out;
}

// A stretch (OM.music({ stretch: bpm })): the ratio to play the track at, or null with the reason.
export function stretchRatio(trackBpm, want) {
  if (!(want > 0)) return { ratio: 1, note: null };
  const r = want / trackBpm;
  if (Math.abs(r - 1) > STRETCH_MAX + 1e-9) return { ratio: 1, note: `stretch ${want} bpm would bend the ${trackBpm.toFixed(2)} bpm track by ${((r - 1) * 100).toFixed(1)} % (the limit is ${STRETCH_MAX * 100} %): ignored` };
  return { ratio: r, note: null };
}

// An analysis played at `ratio` times the speed: every time in it divides by ratio.
